<script lang="ts">
 import LineSidebar from './LineSidebar.svelte';
 import {companion,updateData,notify} from '../state.svelte';import type {Fact,Source,FactRevision} from '../domain';import {DBState} from '../../ts/stores.svelte';
 import {syncPersonalLore,pruneBackups,selectCharacter,selectConversation} from '../bridge.svelte';
 import {profileGroups,profileLabels,factCategory,createFact,editFact,confirmFact,setFactActive,removeFact} from '../companionship';import ConfirmDialog from './ConfirmDialog.svelte';
 let tab=$state<'current'|'history'>('current'),group=$state('all'),statusFilter=$state('all'),factLabel=$state('兴趣'),factValue=$state(''),editing=$state(''),editLabel=$state(''),editValue=$state('');
 let limit=$state(30),confirm=$state<{title:string;description:string;label:string;action:()=>void|Promise<void>}|null>(null);
 let current=$derived(companion.data.facts.filter(f=>(group==='all'||factCategory(f)===group)&&(statusFilter==='all'||statusFilter==='pending'&&!f.confirmed||statusFilter==='active'&&f.confirmed&&f.active!==false||statusFilter==='paused'&&f.active===false)));
 let history=$derived((companion.data.factHistory||[]).filter(h=>group==='all'||(h.after.category||'other')===group));
 let active=$derived(companion.data.facts.filter(f=>f.confirmed&&f.active!==false).length),pending=$derived(companion.data.facts.filter(f=>!f.confirmed).length);
 function run(fn:()=>void){try{fn();syncPersonalLore();}catch(e){notify(String(e).replace(/^Error: /,''));}}
 function add(event:SubmitEvent){event.preventDefault();run(()=>{updateData(data=>createFact(data,factLabel,factValue));factValue='';notify('这项了解已保存，之后也可以改变。');});}
 function edit(fact:Fact){editing=fact.id;editLabel=fact.label;editValue=fact.value;}
 function saveEdit(event:SubmitEvent){event.preventDefault();run(()=>{updateData(data=>editFact(data,editing,editLabel,editValue));editing='';notify('档案已更新，旧版本保留在变化轨迹中。');});}
 function remove(id:string){confirm={title:'移除这项了解与相关历史？',description:'当前条目及它的所有旧版本会删除，并清理本机历史备份；不会继续参与对话。',label:'确认删除',action:async()=>{await pruneBackups(()=>{updateData(data=>removeFact(data,id));syncPersonalLore();});notify('当前条目与相关历史已移除。');}};}
 function toggleConsent(){if(companion.data.preferences.profileEnabled)run(()=>updateData(d=>d.preferences.profileEnabled=false));else confirm={title:'允许当前档案参与陪伴？',description:'只有你确认且未暂停的当前条目会参与对话。旧版本和待确认观察不会发送；可以随时关闭或删除。',label:'确认开启',action:()=>run(()=>{updateData(d=>d.preferences.profileEnabled=true);notify('已开启，你随时可以撤销。');})};}
 async function source(item:Source){const ci=DBState.db.characters.findIndex(c=>c.chaId===item.characterId),ti=DBState.db.characters[ci]?.chats.findIndex(c=>c.id===item.conversationId);if(ci<0||ti===undefined||ti<0){notify('来源对话已不存在。');return;}await selectCharacter(ci);await selectConversation(ti);location.hash='/chat';}
 const names:Record<FactRevision['action'],string>={created:'你新增了一项了解',edited:'你调整了这项了解',confirmed:'你确认了小屿的观察',paused:'你将这项了解暂停',resumed:'你重新启用了这项了解'};
 function when(at:number){return new Date(at).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});}
 function restore(h:FactRevision){confirm={title:'将这版内容设为当前？',description:'这会新增一次修改记录，旧轨迹仍保留。条目的启用/暂停状态保持不变。',label:'设为当前内容',action:()=>run(()=>updateData(data=>editFact(data,h.factId,h.after.label,h.after.value)))};}
 function forgetHistory(){confirm={title:'清除旧版本记录？',description:'清除全部变化轨迹并清理本机历史备份，当前档案内容会继续保留。已导出的副本需另行处理。',label:'清除变化轨迹',action:async()=>{await pruneBackups(()=>updateData(data=>data.factHistory=[]));notify('旧版本轨迹已清除，当前档案仍保留。');}};}
</script>
<div class="profile-archive">
 <div class="profile-layout">
  <aside class="xy-panel profile-card"><img src="/xinyu/art/girl_card.png" alt="我的像素头像"/><h2>{companion.data.preferences.name||'还没留下称呼的你'}</h2><p>小屿慢慢了解你，<br/>也给变化留一个位置。</p><label for="profile-name">希望小屿怎么称呼你</label><input id="profile-name" class="xy-input" value={companion.data.preferences.name} maxlength="30" placeholder="写下喜欢的称呼" onchange={event=>run(()=>updateData(d=>d.preferences.name=event.currentTarget.value.trim().slice(0,30)))}/><div class="profile-summary"><span>当前有效<strong>{active}</strong></span><span>待我确认<strong>{pending}</strong></span></div><LineSidebar items={[{id:'all',label:'全部了解',count:companion.data.facts.length},...Object.entries(profileGroups).map(([id,label])=>({id,label,count:companion.data.facts.filter(f=>factCategory(f)===id).length}))]} selected={group} onselect={id=>group=id} reduced={companion.data.preferences.reduceMotion}/></aside>
  <div class="profile-content">
   <section class="xy-panel profile-consent"><div><h2>由你决定，了解多少</h2><p>{companion.data.preferences.profileEnabled?'只使用你确认、未暂停的当前档案，旧结论不参与对话。':'画像默认关闭。你仍可以整理档案，开启后才用于陪伴。'}</p></div><button class="xy-btn" onclick={toggleConsent}>{companion.data.preferences.profileEnabled?'关闭画像参与':'了解并开启'}</button></section>
   <section class="xy-panel profile-current"><div class="archive-heading"><h2>了解你的陪伴档案</h2><div class="xy-tabs" aria-label="档案视图"><button class:chosen={tab==='current'} aria-pressed={tab==='current'} onclick={()=>tab='current'}>当前档案</button><button class:chosen={tab==='history'} aria-pressed={tab==='history'} onclick={()=>tab='history'}>变化轨迹</button></div></div>
    {#if tab==='current'}<p class="section-description">你主动填写的偏好直接确认；小屿的新观察会先等待你的判断。</p><div class="filter-tabs" aria-label="档案状态">{#each [{id:'all',name:'全部'},{id:'active',name:'当前有效'},{id:'pending',name:'待确认'},{id:'paused',name:'已暂停'}] as item}<button class:chosen={statusFilter===item.id} aria-pressed={statusFilter===item.id} onclick={()=>statusFilter=item.id}>{item.name}</button>{/each}</div>
     {#if current.length}<div class="fact-list">{#each current as fact (fact.id)}<article class:pending={!fact.confirmed} class:paused={fact.active===false}><div class="fact-copy"><small>{profileGroups[factCategory(fact)]} · {fact.origin==='user_provided'?'你主动填写':'模型推断，可能不准'} · {fact.active===false?'已暂停':fact.confirmed?'已确认':'待你确认'}</small><h3>{fact.value}</h3><p class="quiet-note">{fact.label} · {fact.updatedAt?'最近确认/修改 '+when(fact.updatedAt):'记录于 '+when(fact.at)}</p>{#if fact.source}<button class="text-button" onclick={()=>source(fact.source)}>查看证据对话 ↗</button>{/if}</div><div class="fact-actions">{#if !fact.confirmed}<button class="xy-btn" onclick={()=>run(()=>updateData(d=>confirmFact(d,fact.id)))}>确认准确</button>{/if}<button class="text-button" aria-label={'编辑档案：'+fact.value} onclick={()=>edit(fact)}>编辑</button><button class="text-button" aria-label={(fact.active===false?'启用档案：':'暂停档案：')+fact.value} onclick={()=>run(()=>updateData(d=>setFactActive(d,fact.id,fact.active===false)))}>{fact.active===false?'重新启用':'不再适用'}</button><button class="text-button danger-text" aria-label={'移除档案：'+fact.value} onclick={()=>remove(fact.id)}>移除</button></div>
      {#if editing===fact.id}<form class="profile-edit-form" onsubmit={saveEdit}><label for="edit-fact-label">修改偏好类型</label><input id="edit-fact-label" list="profile-label-list" maxlength="40" bind:value={editLabel}/><label for="edit-fact-value">修改偏好内容</label><input id="edit-fact-value" maxlength="200" bind:value={editValue}/><div class="xy-actions"><button class="xy-btn primary" disabled={!editValue.trim()}>保存修改</button><button class="xy-btn" type="button" onclick={()=>editing=''}>取消</button></div></form>{/if}
     </article>{/each}</div>{:else}<div class="module-empty"><h3>给真实的你，留一点空间</h3><p>{group==='all'&&statusFilter==='all'?'先说一件喜欢的事，或希望被怎样陪伴。':'这个分类或状态下还没有条目。'}</p></div>{/if}
     <form class="inline-fact-form" onsubmit={add}><label for="fact-label">偏好类型</label><select id="fact-label" bind:value={factLabel}>{#each profileLabels as name}<option>{name}</option>{/each}</select><label for="fact-value">我的偏好</label><input id="fact-value" bind:value={factValue} maxlength="200" placeholder="例如：难过时，我想先被倾听，再收到建议。"/><button class="xy-btn primary" disabled={!factValue.trim()}>添加偏好</button></form><datalist id="profile-label-list">{#each profileLabels as name}<option value={name}></option>{/each}</datalist>
    {:else}<p class="section-description">保留你怎样改变，而不是把过去的理解固定成现在的你。</p>{#if history.length}<ol class="profile-history">{#each history.slice(0,limit) as h (h.id)}<li><time>{when(h.at)}</time><h3>{names[h.action]}</h3><span class="history-category">{profileGroups[h.after.category||'other']} · {h.after.label}</span>{#if h.before&&h.before.value!==h.after.value}<p class="history-before">之前：{h.before.value}</p>{/if}<p>{h.after.value}</p><small>{h.after.active===false?'当时为暂停状态':h.after.confirmed?'当时已确认':'当时待确认'}</small>{#if h.source}<button class="text-button" onclick={()=>source(h.source)}>来源对话 ↗</button>{/if}{#if companion.data.facts.some(f=>f.id===h.factId&&f.value!==h.after.value)}<button class="text-button" onclick={()=>restore(h)}>恢复这版内容</button>{/if}</li>{/each}</ol>{#if history.length>limit}<button class="xy-btn" onclick={()=>limit+=30}>查看更多变化</button>{/if}{:else}<div class="module-empty"><h3>变化，也可以慢慢发生</h3><p>你对档案的修改会保留在这里，随时可以回来查看。</p></div>{/if}{#if companion.data.factHistory?.length}<button class="text-button danger-text" onclick={forgetHistory}>清除旧版本轨迹</button>{/if}{/if}
   </section><p class="module-caption">临时情绪不会被当成确定的人格。AI 观察需要确认，档案和轨迹可随时删除。</p>
  </div>
 </div>
</div>
{#if confirm}<ConfirmDialog title={confirm.title} description={confirm.description} confirmText={confirm.label} destructive={confirm.label.includes('删除')||confirm.label.includes('清除')} onconfirm={confirm.action} onclose={()=>confirm=null}/>{/if}
